from __future__ import absolute_import

from selenium.webdriver.common.by import By
from taf.selenium.sbts import pages
from taf.selenium.sbts.pages import v23r2


class RndMode(v23r2.RndMode):
    def __init__(self, driver, download_checker):
        super(RndMode, self).__init__(driver, download_checker)
        self._vendor_parameters = VendorParametersPage(driver, download_checker)


class VendorParametersPage(pages.rnd_mode.VendorParametersPage):

    def __init__(self, driver, download_checker):
        super(VendorParametersPage, self).__init__(driver, download_checker)
        self._view_panel = VendorParametersPageViewPanel(driver, download_checker)

    def delete_custom_vendor_file(self):
        self._view_panel.delete_custom_vendor_file()


class VendorParametersPageViewPanel(pages.rnd_mode.VendorParametersPageViewPanel):

    _DELETE_CUSTOM_FILE_XPATH = '//vendor-parameters-delete-button//button'

    def delete_custom_vendor_file(self):
        self.click_enabled_element((By.XPATH, self._DELETE_CUSTOM_FILE_XPATH))
